function openCreator(ch=null){editingCast=ch?.id||null;const vals=ch||baseChar;for(const k of ['name','skin','hair','shirt','pants','hairStyle','glasses','bodyWidth','height','accessory'])$('characterForm').elements[k].value=(ch?vals[k]:k==='name'?'New character':vals[k])||({bodyWidth:'1',height:'1',accessory:'none'}[k]||'');previewChar();$('characterDialog').showModal()}
function charValues(){return Object.fromEntries(new FormData($('characterForm')))}function previewChar(){const c=$('characterPreview').getContext('2d');c.clearRect(0,0,260,320);character(c,charValues(),{...pose,x:130,y:307,scale:.9})}$('newChar').onclick=()=>openCreator();$('characterForm').oninput=previewChar;$('cancelChar').onclick=()=>$('characterDialog').close();$('characterForm').onsubmit=e=>{e.preventDefault();const ch={id:editingCast||uid(),...charValues()};if(editingCast)project.cast=project.cast.map(x=>x.id===editingCast?ch:x);else project.cast.push(ch);save();renderCast();$('characterDialog').close();toast('Saved to your cast. Click the character to add it to a scene.')};
function tab(name){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));$('castTab').hidden=name!=='cast';$('propsTab').hidden=name!=='props';$('sceneTab').hidden=name!=='scene'}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
for(const [type,label]of[['laptop','Laptop'],['plant','Plant'],['coin','Coin'],['arrow','Arrow']]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>newObject(type);$('props').append(b)}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),15000)}$('download').onclick=()=>{save();download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),'elleson-studio-project.json')};$('open').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const p=JSON.parse(await f.text());if(!valid(p))throw Error();stop();project=p;sceneIndex=0;selected=null;time=0;$('title').value=p.title;clearAudio();save();renderCast();render();toast('Project opened. Reattach any voiceover audio.')}catch{toast('This is not a supported Elleson Studio project.')}e.target.value=''};
$('imageFile').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>3e6)return toast('Use an image smaller than 3 MB.');const reader=new FileReader();reader.onload=()=>newObject('image',{name:f.name,src:reader.result});reader.readAsDataURL(f);e.target.value=''};
function clearAudio(){if(audioURL)URL.revokeObjectURL(audioURL);if(audio)audio.pause();audio=null;audioURL=null;$('audioName').textContent='No voiceover · add your narration';$('clearAudio').hidden=true}$('clearAudio').onclick=clearAudio;$('audioFile').onchange=e=>{const f=e.target.files[0];if(!f)return;clearAudio();audioURL=URL.createObjectURL(f);audio=new Audio(audioURL);$('audioName').textContent=f.name+' · session only';$('clearAudio').hidden=false;e.target.value='';toast('Voiceover added. Playback and export use this audio from the start.')};
$('export').onclick=async()=>{if(!window.MediaRecorder||!$('stage').captureStream)return toast('Video export needs a desktop browser with MediaRecorder support.');stop();const oldScene=sceneIndex,oldTime=time;recording=true;document.body.classList.add('recording');toast('Exporting your scenes in real time. Keep this tab open…');let ac,source,rec;try{const stream=$('stage').captureStream(30);if(audio){ac=new AudioContext();await ac.resume();source=ac.createMediaElementSource(audio);const dest=ac.createMediaStreamDestination();source.connect(dest);for(const t of dest.stream.getAudioTracks())stream.addTrack(t);audio.currentTime=0;await audio.play()}
 const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw Error('WebM recording unavailable');rec=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:4000000});const chunks=[];rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};const done=new Promise((resolve,reject)=>{rec.onstop=resolve;rec.onerror=reject});rec.start();for(let i=0;i<project.scenes.length;i++){sceneIndex=i;const s=current();await new Promise(resolve=>{const start=performance.now();function frame(now){time=Math.min(s.duration,(now-start)/1000);draw();if(s.transition==='fade'&&time>s.duration-.35){ctx.globalAlpha=(time-s.duration+.35)/.35;rect(ctx,0,0,960,540,s.bg);ctx.globalAlpha=1}if(time<s.duration)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)})}rec.stop();await done;download(new Blob(chunks,{type:mime}),'elleson-studio-animation.webm');stream.getTracks().forEach(t=>t.stop());toast('Video exported as WebM.')}catch(e){if(rec?.state==='recording')rec.stop();toast('Export unavailable here. Try a current desktop Chrome browser.')}finally{if(audio)audio.pause();if(source)source.disconnect();if(ac){await ac.close();const old=audio;audio=new Audio(audioURL);old.pause()}recording=false;document.body.classList.remove('recording');sceneIndex=oldScene;time=oldTime;render();setTimeout(()=>$('toast').style.display='none',4000)}};
// Scene-first workflow.
const sb=document.createElement('button');sb.dataset.tab='scene';sb.textContent='Scenes';document.querySelector('.tabs').prepend(sb);sb.onclick=()=>tab('scene');const st=document.createElement('div');st.id='sceneTab';st.innerHTML='<p class="note">STEP 1 · SET THE SCENE</p><h3>Start with a backdrop.</h3><div class="scenechoices"><button data-bg="blank">Blank paper <small>A clean canvas for any idea</small></button><button data-bg="studio">Warm studio <small>A soft floor and paper shapes</small></button><button data-bg="board">Chalkboard <small>A space for big explanations</small></button></div><button id="createScene" class="create">＋ Create a new scene</button><p class="note">Next, add objects or open Characters to build your cast. Select a character to animate its joints.</p><div class="row"><button id="sceneLeft">Move earlier</button><button id="sceneRight">Move later</button></div><button id="deleteScene" style="margin-top:10px">Delete this scene</button>';$('castTab').before(st);st.querySelectorAll('[data-bg]').forEach(b=>b.onclick=()=>{current().template=b.dataset.bg;save();draw();toast('Backdrop updated. Add objects, text or characters next.')});function addScene(){stop();project.scenes.push(scene('Scene '+(project.scenes.length+1)));sceneIndex=project.scenes.length-1;selected=null;time=0;tab('scene');save();render()}$('addScene').onclick=$('createScene').onclick=addScene;$('deleteScene').onclick=()=>{if(project.scenes.length===1)return toast('Keep at least one scene.');if(!confirm('Delete this scene and its objects?'))return;stop();project.scenes.splice(sceneIndex,1);sceneIndex=Math.max(0,sceneIndex-1);selected=null;time=0;save();render()};for(const[id,d]of[['sceneLeft',-1],['sceneRight',1]])$(id).onclick=()=>{const j=sceneIndex+d;if(j<0||j>=project.scenes.length)return;[project.scenes[j],project.scenes[sceneIndex]]=[project.scenes[sceneIndex],project.scenes[j]];sceneIndex=j;save();render()};


function applyMotion(o,kind){if(o.locked)return toast('Unlock this layer before editing.');stop();const start=Math.min(time,current().duration-.1),end=Math.min(start+2,current().duration),v=stateAt(o,start),frames=[];const push=(t,vv)=>frames.push({t:Math.round(t*100)/100,v:{...vv}});push(start,v);if(kind==='wave'){for(let i=1;i<=4;i++)push(start+(end-start)*i/4,{...v,...presets.Wave,rightElbow:i%2?-55:-10})}else if(kind==='explain'){push(start+(end-start)*.5,{...v,...presets.Explain});push(end,{...v,...presets.Point})}else if(kind==='walk'){for(let i=1;i<=8;i++)push(start+(end-start)*i/8,{...v,x:Math.min(860,v.x+220*i/8),leg:i%2?20:-20,leftArm:i%2?-25:25,rightArm:i%2?25:-25});push(Math.min(current().duration,end+.1),{...v,x:Math.min(860,v.x+220)})}else{frames[0].v={...v,opacity:0,y:v.y+25};push(end,{...v,opacity:1})}o.keys=o.keys.filter(k=>k.t<start||k.t>frames.at(-1).t);for(const f of frames){const existing=o.keys.find(k=>k.t===f.t);if(existing)existing.v=f.v;else o.keys.push(f)}o.keys.sort((a,b)=>a.t-b.t);save();render();toast('Animation added. Press play to preview.');}
function restoreHistory(snap){stop();project=JSON.parse(snap);sceneIndex=Math.min(sceneIndex,project.scenes.length-1);selected=null;time=0;time=Math.min(time,current().duration);try{localStorage.setItem('paperpop-v1',snap)}catch{toast('Storage full. Download a project backup.')}renderCast();render()}
$('undo').onclick=()=>{if(historyStack.length<2)return toast('Nothing to undo yet.');futureStack.push(historyStack.pop());restoreHistory(historyStack.at(-1))};$('redo').onclick=()=>{if(!futureStack.length)return toast('Nothing to redo yet.');const snap=futureStack.pop();historyStack.push(snap);restoreHistory(snap)};
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-step]').forEach(x=>x.classList.toggle('active',x===b));const mode=b.dataset.step;if(mode==='animate'){if(!object()||object().type!=='character'){const ch=current().objects.find(o=>o.type==='character');if(ch){selected=ch.id;render()}else{tab('cast');toast('Add a character to this scene, then animate it.');document.querySelector('.library').scrollIntoView({behavior:'smooth',block:'start'});return}}document.querySelector('.inspector').scrollIntoView({behavior:'smooth',block:'start'})}else{tab(mode);document.querySelector('.library').scrollIntoView({behavior:'smooth',block:'start'})}});

// Validate imported and autosaved extension fields before rendering or decoding assets.
function valid(p){
 try {
  const color=v=>typeof v==='string'&&/^#[0-9a-f]{6}$/i.test(v);
  const image=v=>typeof v==='string'&&v.length<18000000&&/^data:image\/(png|jpeg|webp|gif);base64,/i.test(v);
  const char=c=>c&&typeof c.name==='string'&&['skin','hair','shirt','pants'].every(k=>color(c[k]))&&['bodyWidth','height'].every(k=>c[k]===undefined||(Number.isFinite(Number(c[k]))&&Number(c[k])>=.5&&Number(c[k])<=2));
  if(!validCore(p)||typeof p.title!=='string'||p.title.length>500||!p.cast.every(char))return false;
  const ids=new Set();
  return p.scenes.every(s=>{
   if(ids.has(s.id))return false;ids.add(s.id);
   if(s.backgroundImage!==undefined&&!image(s.backgroundImage))return false;
   if(s.backgroundFit!==undefined&&!['cover','contain'].includes(s.backgroundFit))return false;
   if(s.camera&&!['start','end'].every(k=>{const c=s.camera[k];return c&&Number.isFinite(c.zoom)&&c.zoom>=1&&c.zoom<=3&&Number.isFinite(c.x)&&c.x>=0&&c.x<=960&&Number.isFinite(c.y)&&c.y>=0&&c.y<=540}))return false;
   if(s.captions!==undefined&&(!Array.isArray(s.captions)||s.captions.length>10000||!s.captions.every(c=>c&&Number.isFinite(c.start)&&Number.isFinite(c.end)&&c.start>=0&&c.end>c.start&&c.end<=s.duration&&typeof c.text==='string'&&c.text.length<=10000)))return false;
   const layers=new Set();return s.objects.every(o=>{
    if(layers.has(o.id))return false;layers.add(o.id);
    return typeof o.name==='string'&&(!o.group||typeof o.group==='string')&&['locked','hidden','lipSync'].every(k=>o[k]===undefined||typeof o[k]==='boolean')&&(o.type!=='character'||char(o.character))&&(o.type!=='image'||image(o.src))&&(o.type!=='text'||typeof o.text==='string')&&(o.type!=='video'||typeof o.src==='string'&&/^data:video\/[a-z0-9.+-]+;base64,/i.test(o.src)&&Number.isFinite(o.sourceDuration)&&o.sourceDuration>0&&Number.isFinite(o.sourceOffset)&&o.sourceOffset>=0&&Number.isFinite(o.width)&&o.width>0&&o.width<=960&&Number.isFinite(o.height)&&o.height>0&&o.height<=960)&&o.keys.every(k=>k.t>=0&&k.t<=s.duration&&k.v.scale>0&&k.v.scale<=20&&k.v.opacity>=0&&k.v.opacity<=1);
   });
  });
 }catch{return false}
}
